    18→const MAX_NAME_LENGTH = 64;
    19→const MAX_CREDENTIAL_LENGTH = 256;
    20→
    21→function validateCredential(value: string, field: string): string | null {
    22→  const trimmed = value.trim();
    23→  if (!trimmed) return `${field} cannot be empty`;
    24→  if (trimmed.length > MAX_CREDENTIAL_LENGTH) return `${field} exceeds max length (${MAX_CREDENTIAL_LENGTH})`;
    25→  return null;
    26→}
    27→
    28→function validateName(name: string): string | null {
    29→  const trimmed = name.trim();
    30→  if (!trimmed) return "name cannot be empty";
    31→  if (trimmed.length > MAX_NAME_LENGTH) return `name exceeds max length (${MAX_NAME_LENGTH})`;
    32→  return null;
    33→}
    34→
    35→function toAccount(record: AccountRecord): Account {
    36→  return {
    37→    id: record.id,
    38→    exchange: record.exchange,
    39→    name: record.name,
    40→    created_at: record.created_at,
    41→    updated_at: record.updated_at,
    42→  };
    43→}
    44→
    45→export async function findAccount(idOrName: string): Promise<AccountRecord | null> {
    46→  const accounts = await readAccounts();
    47→  // 1. Match by ID
    48→  const byId = accounts.find((a) => a.id === idOrName);
    49→  if (byId) return byId;
    50→  // 2. Match by name (exact, case-sensitive)
    51→  const byName = accounts.filter((a) => a.name === idOrName);
    52→  if (byName.length === 1) return byName[0];
    53→  if (byName.length > 1) return null; // ambiguous
    54→  return null;
    55→}
    56→
    57→export async function listAccounts(): Promise<ListAccountsResult> {
    58→  const accounts = await readAccounts();
    59→  return { success: true, accounts: accounts.map(toAccount) };
    60→}
    61→
    62→export async function addAccount(input: {
    63→  exchange: ExchangeId;
    64→  name: string;
    65→  api_key: string;
    66→  secret: string;
    67→  passphrase?: string;
    68→}): Promise<CreateAccountResult> {
    69→  // Validate
    70→  const nameErr = validateName(input.name);
    71→  if (nameErr) return { success: false, error: nameErr };
    72→
    73→  const keyErr = validateCredential(input.api_key, "api_key");
    74→  if (keyErr) return { success: false, error: keyErr };
    75→
    76→  const secretErr = validateCredential(input.secret, "secret");
    77→  if (secretErr) return { success: false, error: secretErr };
    78→
    79→  const exchange = getExchange(input.exchange);
    80→  if (exchange.fields.includes("passphrase")) {
    81→    if (!input.passphrase) return { success: false, error: "passphrase is required for " + exchange.name };
    82→    const ppErr = validateCredential(input.passphrase, "passphrase");
    83→    if (ppErr) return { success: false, error: ppErr };
    84→  }
    85→
    86→  const now = new Date().toISOString();
    87→  const record: AccountRecord = {
    88→    id: nanoid(12),
    89→    exchange: input.exchange,
    90→    name: input.name.trim(),
    91→    api_key: input.api_key.trim(),
    92→    secret: input.secret.trim(),
    93→    passphrase: input.passphrase?.trim(),
    94→    created_at: now,
    95→    updated_at: now,
    96→  };
    97→
    98→  const accounts = await readAccounts();
    99→  accounts.push(record);
   100→  await writeAccounts(accounts);
   101→
   102→  return { success: true, account: toAccount(record) };
   103→}
