   105→export async function viewAccount(idOrName: string): Promise<ViewAccountResult> {
   106→  const record = await findAccount(idOrName);
   107→  if (!record) {
   108→    // Check if ambiguous name
   109→    const accounts = await readAccounts();
   110→    const byName = accounts.filter((a) => a.name === idOrName);
   111→    if (byName.length > 1) {
   112→      return { success: false, error: `Multiple accounts match name "${idOrName}". Use account ID instead.` };
   113→    }
   114→    return { success: false, error: `Account not found: ${idOrName}` };
   115→  }
   116→
   117→  const exchange = getExchange(record.exchange);
   118→  const masked: Partial<Record<CredentialField, string>> = {};
   119→  for (const field of exchange.fields) {
   120→    const value = record[field as keyof AccountRecord] as string | undefined;
   121→    if (value) masked[field] = maskCredential(value);
   122→  }
   123→
   124→  return { success: true, account: toAccount(record), masked_credentials: masked };
   125→}
   126→
   127→export async function updateAccount(idOrName: string, input: {
   128→  name?: string;
   129→  api_key?: string;
   130→  secret?: string;
   131→  passphrase?: string;
   132→}): Promise<UpdateAccountResult> {
   133→  const accounts = await readAccounts();
   134→  // Check for ambiguous name match
   135→  const byName = accounts.filter((a) => a.name === idOrName);
   136→  if (byName.length > 1) {
   137→    return { success: false, error: `Multiple accounts match name "${idOrName}". Use account ID instead.` };
   138→  }
   139→  const idx = accounts.findIndex((a) => a.id === idOrName || a.name === idOrName);
   140→  if (idx === -1) return { success: false, error: `Account not found: ${idOrName}` };
   141→
   142→  const record = accounts[idx];
   143→
   144→  if (input.name) {
   145→    const nameErr = validateName(input.name);
   146→    if (nameErr) return { success: false, error: nameErr };
   147→    record.name = input.name.trim();
   148→  }
   149→  if (input.api_key) {
   150→    const err = validateCredential(input.api_key, "api_key");
   151→    if (err) return { success: false, error: err };
   152→    record.api_key = input.api_key.trim();
   153→  }
   154→  if (input.secret) {
   155→    const err = validateCredential(input.secret, "secret");
   156→    if (err) return { success: false, error: err };
   157→    record.secret = input.secret.trim();
   158→  }
   159→  if (input.passphrase !== undefined) {
   160→    if (input.passphrase) {
   161→      const err = validateCredential(input.passphrase, "passphrase");
   162→      if (err) return { success: false, error: err };
   163→      record.passphrase = input.passphrase.trim();
   164→    } else {
   165→      record.passphrase = undefined;
   166→    }
   167→  }
   168→
   169→  record.updated_at = new Date().toISOString();
   170→  accounts[idx] = record;
   171→  await writeAccounts(accounts);
   172→
   173→  return { success: true, account: toAccount(record) };
   174→}
   175→
   176→export async function removeAccount(idOrName: string): Promise<RemoveAccountResult> {
   177→  const accounts = await readAccounts();
   178→  const byName = accounts.filter((a) => a.name === idOrName);
   179→  if (byName.length > 1) {
   180→    return { success: false, error: `Multiple accounts match name "${idOrName}". Use account ID instead.` };
   181→  }
   182→  const idx = accounts.findIndex((a) => a.id === idOrName || a.name === idOrName);
   183→  if (idx === -1) return { success: false, error: `Account not found: ${idOrName}` };
   184→
   185→  accounts.splice(idx, 1);
   186→  await writeAccounts(accounts);
   187→
   188→  return { success: true };
   189→}
